package assignment1;

public class Prog100CrossPattern {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		 int rows = 5; 
	        for (int i = 0; i < rows; i++) {
	            if (i == 0 || i == rows - 1) {
	              
	                System.out.println("***");
	            } else {
	               
	                System.out.println(" * ");
	            }
	        }
	//hfjfjf	
		
	}

}
